    {
      "category": "bridged_nets",
      "components": ["U2", "U3", "J4", "R3", "U1"],
      "pins": ["U2.1", "U3.1", "J4.5", "J4.6", "U1.1", "U2.4", "U3.4", "R3.2"],
      "nets": ["RST"],
      "observed": "The net named RST contains both reset pins and ground pins: U2.1, U3.1, and J4.5 are tied to the same net as U1.1, U2.4, U3.4, J4.6, and other GND connections.",
      "expected": "GND and RST should be separate nets. For an ATtiny-based controller, the active-low reset/ISP reset line should be pulled up to +5V (via R3) and not tied directly to ground.",
      "evidence": [
        {"source": "netlist", "quote": "J4.5(~{RST},passive) J4.6(GND,passive)"},
        {"source": "netlist", "quote": "U2.1(~{RESET}/PB5,bidirectional) U2.4(GND,power_in)"},
        {"source": "spec", "quote": "an ATtiny-driven fan controller"}
      ],
      "impact": "If the ATtiny reset fuse is enabled, the MCU(s) are held in reset and the fan controller cannot run; the AVR-ISP reset pin is also shorted to ground, which can prevent normal programming.",
      "confidence": 0.84
    }
  ],
  "summary": "The design files show the RST net merged with ground, tying ATtiny reset pins and the ISP reset pin to GND; this is a likely fatal connectivity anomaly."
}

